    'SettingsBackupsDesc'                 => 'Configurați păstrarea copiilor de rezervă, programarea și linkurile de descărcare pentru copiile de rezervă ale bazei de date SimpleRisk.',
    'SettingsSecurityDesc'                => 'Setări de securitate pentru autentificare, sesiune, politică de parolă, URL de bază și API.',
    'SettingsLoggingDesc'                 => 'Configurarea jurnalizării de depanare și audit: nivelurile de jurnalizare, păstrarea și locația fișierelor jurnal.',
    'HealthCheckDesc'                     => 'Diagnosticați starea sistemului: versiunea PHP, extensiile, permisiunile fișierelor, conectivitatea bazei de date, programul cron și activările Extra.',
    'AnnouncementsDesc'                   => 'Redactați și gestionați anunțuri tip banner vizibile pentru toți utilizatorii.',
    'RegisterAndUpgradeDesc'              => 'Înregistrați instalarea SimpleRisk, introduceți sau reînnoiți o cheie de abonament și declanșați actualizări Core/Extra dintr-un singur clic.',
    'QueueMonitorDesc'                    => 'Inspectați coada de joburi în fundal: joburi în așteptare, în curs de desfășurare și eșuate.',
    'ExtrasDesc'                          => 'Activați, dezactivați și configurați Extra-urile SimpleRisk (suplimente plătite).',
    'ArtificialIntelligenceExtraDesc'     => 'Artificial Intelligence Extra oferă analize îmbunătățite ale riscurilor (inclusiv evaluări FAIR) și documentație personalizată.',
    'CustomizationExtraDesc'              => 'Extra-ul Customization oferă posibilitatea de a adăuga și elimina diferite tipuri de câmpuri și de a crea dinamic șabloane de pagini personalizate.',
    'NotificationExtraDesc'               => 'Extra-ul Email Notification permite SimpleRisk să trimită notificări prin e-mail atunci când riscurile sunt trimise, modificate sau când se întreprinde o altă acțiune asupra lor. Acest Extra poate fi adăugat și ca script programat pentru a trimite mementouri periodice atunci când riscurile sunt pregătite pentru o revizuire de management. În produsul SimpleRisk Core, fără acest Extra, nu se comunică nicio notificare în afara instrumentului în sine.',
    'VulnerabilityManagementExtraDesc'    => 'Extra-ul Vulnerability Management oferă clienților posibilitatea de a integra instanța SimpleRisk cu Qualys, Tenable.io sau Rapid7 Nexpose/InsightVM și de a importa în SimpleRisk atât date despre active, cât și despre vulnerabilități. De acolo, puteți selecta site-urile pe care doriți să le acoperiți, puteți stabili ce scoruri de vulnerabilitate trebuie importate și puteți tria vulnerabilitățile care sunt transformate în riscuri pentru a le urmări.',
    'IncidentManagementExtraDesc'         => 'Incident Management Extra se bazează pe Ghidul NIST 800-61 pentru gestionarea incidentelor de securitate informatică și oferă capabilități de gestionare a incidentelor din cadrul sistemului SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Redenumiți terminologia SimpleRisk (risc, activ, cadru etc.) în întreaga interfață.',
    'RiskConfigurationDesc'               => 'Configurați regulile de calcul al scorului riscurilor: niveluri, apetit, praguri SLA și formulele de risc clasice / cu factori contributivi.',
    'RiskAndThreatCatalogDesc'            => 'Întrețineți catalogul de valori de risc și de amenințare utilizate în listele derulante.',
    'AddAndRemoveValuesDesc'              => 'Gestionați valorile din meniul derulant pentru câmpurile de risc: locație, sursă, categorie, echipă, tehnologie și altele.',
    'AssetValuationDesc'                  => 'Configurați scala de evaluare a activelor și suprascrierile de evaluare per activ.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Adăugați, editați, dezactivați și resetați utilizatori; gestionați politica de parole.',
    'RoleManagementDesc'                  => 'Definiți rolurile și permisiunile pe care le acordă fiecare rol.',
    'TeamManagementDesc'                  => 'Creați și gestionați echipe utilizate pentru filtrarea vizibilității înregistrărilor.',
    'SeparationExtraDesc'                 => 'Funcția Extra de Separare Bazată pe Echipă restricționează vizualizarea riscurilor doar la utilizatorii care sunt membri ai echipei căreia îi este atribuit riscul. În produsul SimpleRisk Core, fără această funcție Extra, fiecare utilizator poate vedea fiecare risc.',
    'CustomAuthenticationExtraDesc'       => 'Extra-ul de autentificare personalizată oferă suport pentru autentificarea Active Directory și SAML. În produsul SimpleRisk Core, fără acest Extra, singura opțiune este crearea de utilizatori noi în depozitul de identități SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Instrumentul Encrypted Database Extra generează o cheie de criptare AES-256 biți aleatorie și apoi o folosește pentru a cripta textul sensibil înainte de a fi introdus în baza de date SimpleRisk. Acest lucru împiedică oricine să poată vizualiza sau modifica datele fără a utiliza direct aplicația SimpleRisk.',
    'OrganizationManagementDesc'          => 'Extra-ul Organizational Hierarchy oferă posibilitatea de a defini mai multe unități de business care pot include un număr oricât de mare de echipe. Utilizatorii pot fi apoi atribuiți uneia sau mai multor echipe din diverse unități de business. Acest lucru afectează posibilitatea unui utilizator de a vedea și utiliza echipele, utilizatorii și activele cu care nu este asociat.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Ștergere în bloc a riscurilor. Folosiți cu moderație - ștergerile sunt permanente.',
    'AuditTrailDesc'                      => 'Căutați și exportați jurnalul de audit al sistemului pentru acțiunile utilizatorilor.',
    'ImportExportExtraDesc'               => 'Extra-ul Import-Export oferă posibilitatea de a importa date în SimpleRisk prin maparea câmpurilor dintr-un fișier CSV la câmpurile din baza de date SimpleRisk. Poate fi utilizat pentru a importa rezultate de audit dintr-o foaie de calcul terță, rezultate ale scanărilor de vulnerabilități din alt instrument, active din CMDB și altele. Extra-ul oferă și posibilitatea de a exporta din SimpleRisk fișiere CSV care conțin riscuri, atenuări, revizuiri sau un raport combinat al celor trei.',
    'JiraExtraDesc'                       => 'Jira Integration Extra oferă utilizatorilor posibilitatea de a se integra bidirecțional cu o instanță Jira. Permite conectarea riscurilor la problemele Jira, precum și sincronizarea datelor, stării și comentariilor acestora.',
    'APIExtraDesc'                        => 'Extra-ul API permite clienților să utilizeze un API RESTful pentru a crea interacțiuni scriptate cu alte aplicații, pentru a obține o automatizare avansată și a valorifica infrastructura existentă.',
    'AdvancedSearchExtraDesc'             => "Funcția Căutare Avansată Extra transformă caseta de căutare din bara superioară într-o singură căutare pentru riscuri, cadre de lucru, controale, documente, excepții, teste, audituri, active și grupuri de active, cu o pagină de căutare completă pentru parcurgerea rezultatelor. Afișează doar înregistrările pe care utilizatorul are permisiunea să le vadă.",
    'AssessmentsExtraDesc'                => 'Extra-ul Risk Assessment oferă utilizatorilor posibilitatea de a defini contacte, de a crea întrebări (inclusiv logică), de a asambla mai multe întrebări într-un șablon de chestionar, de a crea chestionare și de a le trimite contactelor, de a vedea rezultatele chestionarelor, de a adăuga riscuri pe baza acestor rezultate, de a compara rezultatele în timp, de a importa și exporta evaluări personalizate extern și de a revizui jurnalul de audit al evaluărilor de risc.',
    'ActiveAssessmentsDesc'               => 'Vizualizați și gestionați evaluările aflate în curs de desfășurare.',
    'WorkflowsExtraDesc'                  => 'Workflows Extra oferă un motor vizual de fluxuri de lucru bazat pe evenimente, care automatizează acțiunile de gestionare a riscurilor ca răspuns la evenimentele din SimpleRisk. Puteți proiecta fluxuri de lucru care se declanșează la modificări - cum ar fi trimiterea, actualizarea sau revizuirea unui risc - pentru a direcționa aprobările, a atribui sarcini și a menține procesul în mișcare fără intervenție manuală.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Extra Secure Controls Framework (SCF) este o integrare directă între Secure Controls Framework și SimpleRisk. Importă în funcționalitatea Governance din SimpleRisk catalogul de controale al SCF și mapările acestora pentru o gamă largă de cadre de conformitate și securitate cibernetică, astfel încât să puteți adopta cadrele de care aveți nevoie și să gestionați controalele acestora fără a le crea manual.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Migrați coloanele vechi de tip varchar pentru datele de revizuire către tipuri de dată corespunzătoare. Vizibil doar când este necesar.',
    'DatabaseUpgradeDesc'                 => 'Declanșați manual rutina de actualizare a bazei de date SimpleRisk.',

