    'EncryptionActivationFailedTitle'       => 'Activarea criptării a eșuat',
    'EncryptionActivationFailedBody'        => 'Activarea nu a putut fi finalizată, iar baza de date poate fi într-o stare inconsistentă. Copia de rezervă dinaintea activării este păstrată — utilizați Restaurare din copia de rezervă pentru recuperare sau contactați asistența SimpleRisk.',
    'EncryptionDeactivationInProgress'      => 'Se decriptează baza de date SimpleRisk. Vă rugăm să nu închideți această pagină.',
