    'ApplicabilityAppliesToAllFiltered' => 'Va fi înregistrată pentru toate cele {$n} controale care corespund filtrelor curente, inclusiv cele de pe alte pagini.',
    // Per-state hints under the segmented control. The "applicable" one is the
