    // someone who cannot take it.
    'HowDoYouWantToAddAFramework' => 'Cum doriți să adăugați un cadru?',
    'CreateFrameworkManually' => 'Creați unul manual',
    'CreateFrameworkManuallyHint' => 'Denumiți singur cadrul, apoi adăugați sau mapați controalele sale.',
    // Named for the framework rather than for its vendor. The hint was reworded
