    'GetFrameworkFromScf' => 'Obțineți unul din Secure Controls Framework',
    'GetFrameworkFromScfHint' => 'Alegeți un cadru publicat și încărcați controalele sale mapate într-un singur pas.',
    'ImportFrameworkFromCatalog' => 'Importați unul',
    'ImportFrameworkFromCatalogHint' => 'Instalați un cadru și controalele sale din catalogul de conținut SimpleRisk.',

    // The framework acquisition chooser's third route, which now offers the
    // Import-Export Extra's CONTROL import (a spreadsheet naming a framework
