    'EncryptionPipelineStalledTask' => 'Un flux de criptare (sarcina #{$id}, {$type}) pare blocat — este în starea {$status} de o perioadă neobișnuit de lungă, fără progres. De obicei, aceasta înseamnă că procesorul cozii de fundal nu rulează; verificați dacă este programat, apoi încercați din nou după ce a procesat sarcina blocată.',
    'EncryptionPipelineStalledState' => 'Un flux de criptare pare blocat — a fost marcat ca în curs de o perioadă neobișnuit de lungă, fără nicio sarcină de fundal corespunzătoare la care să se facă referire. De obicei, aceasta înseamnă că procesorul cozii nu rulează sau că un flux anterior s-a încheiat fără a actualiza corect această stare. Verificați jurnalul de depanare înainte de a încerca din nou.',
    // DEMO_MODE — shown when a visitor to a shared demo instance attempts one
