    'QuestionnaireRequiredQuestionUnanswered' => 'Vă rugăm să răspundeți la toate întrebările obligatorii înainte de a finaliza evaluarea.',
    'AuditLog_ControlStatusAutoSynced' => 'Starea controlului „{$short_name}” a fost actualizată automat la „{$status_text}” pe baza celor mai recente rezultate ale testelor.',
    'EnableCSPHelp' => 'Politica de securitate a conținutului (CSP) restricționează browserul să încarce scripturi, stiluri, imagini și fonturi doar de la SimpleRisk însuși și blochează încadrarea paginilor și trimiterea de formulare între origini diferite. Este cea mai puternică apărare integrată împotriva atacurilor de tip cross-site scripting. Lăsați-o activată, cu excepția cazului în care intră în conflict cu un proxy, o extensie de browser sau o integrare terță din mediul dvs.',
    // Define Control Frameworks' Columns picker (Task: Columns picker + saved layout/filters) -- the "Standard" group label above its built-in fields (Family/Owner/Maturity/Status/Class/Phase/Priority/Type); 'CustomFields' already exists.
