    'AssetScoring' => 'Scorarea activelor',
    'AssetScoringSettingsHint' => 'Fiecare activ este evaluat cu nivelul Scăzut, Moderat sau Ridicat pentru confidențialitate, integritate și disponibilitate, iar confidențialitatea poate fi în schimb Neaplicabil, ceea ce o exclude din ambele rezultate. Categorizarea sa FIPS este cea mai ridicată dintre cele trei evaluări. Scorul său ponderat este media ponderată a celor trei valori de nivel, iar pragurile intervalelor transformă acest scor într-un interval Scăzut, Moderat sau Ridicat. Modificarea acestor setări recalculează imediat scorul fiecărui activ.',
